  const scriptBase=new URL('.',document.currentScript?.src||location.href);
  const defaults=()=>({type:'scatter',name:'',mapping:{x:'',y:'',label:'',group:'',estimate:'',lower:'',upper:'',mean:'',error:''},font:'Arial',fontSize:7,width:'double',widthMM:180,palette:'okabe',xTitle:'',yTitle:'',legend:true,maxLabels:8,annotated:[],reference:'0',observation:'',replication:'',uncertainty:'',methods:'',specificationId:'',specificationSourceUrls:[]});
  let state={schema:'yeastvar-lab/v1',formulas:[],figure:defaults(),dataset:null},tab='formulas',editing='',removed=null,root=null,controller=null,search='',rowPage=0,timer=null,lastPlot=null,katexPromise=null,pendingSpecification=null;
  const A=()=>window.YV_APP;
  const lang=()=>LANGS.indexOf(A()?.prefs()?.language||'zh');
  const T=k=>window.YV_LAB_TEXT?.[k]?.[Math.max(0,lang())]||k;
  const E=v=>String(v??'').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const S=(v,n=5000)=>typeof v==='string'?v.slice(0,n):'';
  const num=v=>typeof v==='number'&&Number.isFinite(v)?v:NaN;
