  function cleanFormula(f){if(!f||typeof f!=='object')throw Error(T('invalidJSON'));return {id:S(f.id,100)||uid(),name:S(f.name,240),text:S(f.text),latex:S(f.latex,4000),variables:S(f.variables),units:S(f.units,1000),assumptions:S(f.assumptions),sourceURL:safeURL(S(f.sourceURL,2000)),stage:S(f.stage,100),metric:S(f.metric,100),tool:S(f.tool,100),enabled:f.enabled===true,updatedAt:S(f.updatedAt,50)};}
  function cleanFigure(f){const c=defaults();if(!f||typeof f!=='object')return c;for(const k of ['name','xTitle','yTitle','observation','replication','uncertainty','methods','specificationId'])c[k]=S(f[k],3000);for(const k of Object.keys(c.mapping))c.mapping[k]=S(f.mapping?.[k],240);c.type=['scatter','effect','bar'].includes(f.type)?f.type:c.type;c.font=['Arial','Helvetica','Verdana'].includes(f.font)?f.font:c.font;c.fontSize=Math.max(5,Math.min(12,num(f.fontSize)||7));c.width=['single','double','custom'].includes(f.width)?f.width:c.width;c.widthMM=Math.max(60,Math.min(300,num(f.widthMM)||180));c.palette=['okabe','tol'].includes(f.palette)?f.palette:'okabe';c.legend=f.legend!==false;c.maxLabels=Math.max(0,Math.min(24,Math.round(num(f.maxLabels)||0)));c.annotated=Array.isArray(f.annotated)?[...new Set(f.annotated.filter(x=>Number.isInteger(x)&&x>=0&&x<5000))]:[];c.reference=['none','0','1'].includes(String(f.reference))?String(f.reference):'0';c.specificationSourceUrls=Array.isArray(f.specificationSourceUrls)?f.specificationSourceUrls.map(safeURL).filter(Boolean).slice(0,20):[];return c;}
  function cleanDataset(d){if(d==null)return null;if(!d||!Array.isArray(d.columns)||!Array.isArray(d.rows)||d.columns.length>80||d.rows.length>5000)throw Error(T('invalidJSON'));const columns=d.columns.map(x=>S(x,240));if(!columns.length||columns.some(x=>!x.trim())||new Set(columns).size!==columns.length)throw Error(T('parseError'));const rows=d.rows.map(r=>{if(!Array.isArray(r)||r.length!==columns.length||r.some(x=>typeof x!=='string'||x.length>50000))throw Error(T('parseError'));return [...r];});if(JSON.stringify(rows).length>2500000)throw Error(T('limitError'));return {name:S(d.name,240)||'data.csv',columns,rows,importedAt:S(d.importedAt,50)||new Date().toISOString()};}
  function normalize(x){if(!x||x.schema!=='yeastvar-lab/v1'||!Array.isArray(x.formulas)||x.formulas.length>500)throw Error(T('invalidJSON'));return {schema:'yeastvar-lab/v1',formulas:x.formulas.map(cleanFormula),figure:cleanFigure(x.figure),dataset:cleanDataset(x.dataset)};}
  try{const old=localStorage.getItem(KEY);if(old)state=normalize(JSON.parse(old));}catch{}
