  function status(text){const s=$('#lab-status');if(s){s.textContent=text;s.hidden=false;}else A()?.toast?.(text);}
  function exportData({enabledOnly=false}={}){return JSON.parse(JSON.stringify({...state,formulas:(enabledOnly?state.formulas.filter(f=>f.enabled):state.formulas).map(f=>({...f,bindingWarnings:['stage','metric','tool'].filter(k=>f[k]&&!validBinding(k,f[k])).map(k=>({kind:k,id:f[k],status:'absent_from_current_catalogue'}))})),exportedAt:new Date().toISOString(),guides:[GUIDE,SIZE_GUIDE]}));}
  function importData(value,{merge=true}={}){const incoming=normalize(typeof value==='string'?JSON.parse(value):value);if(merge){const map=new Map(state.formulas.map(f=>[f.id,f]));incoming.formulas.forEach(f=>map.set(f.id,f));incoming.formulas=[...map.values()].slice(0,500);}state=incoming;editing='';search='';rowPage=0;save();refresh();status(T('imported'));return exportData();}
  function download(name,data,type){const u=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
  const title=(kind,item)=>A()?.field?.(kind,item,'name')||A()?.tx?.(item.name||item.title)||item.name||item.title||item.id;
