  function formulaEditor(){const f=state.formulas.find(x=>x.id===editing)||{};return `<section class="lab-card lab-formula-editor"><div class="lab-card-head"><span class="lab-step">01</span><h2>${T(editing?'editing':'newFormula')}</h2></div><form id="lab-formula-form">${input('name','name',f.name,'required maxlength="240"')}${area('text','formulaText',f.text)}${area('latex','latex',f.latex,4000)}<div class="lab-math-preview" id="lab-math-preview" aria-label="${T('preview')}"></div><div class="lab-two">${area('variables','variables',f.variables)}${area('units','units',f.units,1000)}</div>${area('assumptions','assumptions',f.assumptions)}${input('sourceURL','source',f.sourceURL,'type="url" maxlength="2000" placeholder="https://doi.org/…"')}<div class="lab-three">${['stage','metric','tool'].map(k=>`<label class="lab-field"><span>${T(k)}</span><select name="${k}">${choices(k,f[k])}</select></label>`).join('')}</div><label class="lab-check"><input name="enabled" type="checkbox" ${f.enabled?'checked':''}>${T('enabled')}</label><div class="lab-actions"><button class="btn btn-primary" type="submit">${T('save')}</button>${editing?`<button class="btn" type="button" data-lab="cancel">${T('cancel')}</button>`:''}</div></form></section>`;}
  function formulaList(){return `<section class="lab-card"><div class="lab-card-head"><span class="lab-step">02</span><h2>${T('formulas')} <small>${state.formulas.length}</small></h2></div>${removed?`<button class="btn" data-lab="restore">↶ ${T('restore')}</button>`:''}<div class="lab-formula-list">${state.formulas.length?state.formulas.map(f=>`<article class="lab-formula-record" data-formula-id="${E(f.id)}"><header><h3>${E(f.name||T('emptyTitle'))}</h3><label class="lab-check"><input type="checkbox" data-lab-enable="${E(f.id)}" ${f.enabled?'checked':''}>${T('enabled')}</label></header><div class="lab-formula-render" data-formula-latex="${E(f.id)}">${E(f.latex||f.text)}</div>${f.text?`<p>${E(f.text)}</p>`:''}<dl>${['variables','units','assumptions'].filter(k=>f[k]).map(k=>`<dt>${T(k)}</dt><dd>${E(f[k])}</dd>`).join('')}${['stage','metric','tool'].filter(k=>f[k]).map(k=>`<dt>${T(k)}</dt><dd>${validBinding(k,f[k])?`<button data-action="open" data-kind="${k==='stage'?'step':k}" data-id="${E(f[k])}">${E(bindingLabel(k,f[k]))} ↗</button>`:`<span class="lab-issue">${E(f[k])} · ${T('invalidBinding')}</span>`}</dd>`).join('')}</dl>${f.sourceURL?`<a href="${E(f.sourceURL)}" target="_blank" rel="noopener noreferrer">${T('source')} ↗</a>`:''}<footer><button class="btn" data-lab="edit" data-id="${E(f.id)}">${T('edit')}</button><button class="btn btn-quiet" data-lab="delete" data-id="${E(f.id)}">${T('remove')}</button></footer></article>`).join(''):`<div class="lab-empty"><span>∑</span><p>${T('emptyFormula')}</p></div>`}</div></section>`;}
  function bindingLabel(kind,id){const d=A()?.data()?.workflow;const a=kind==='stage'?d?.steps:kind==='metric'?d?.metrics:d?.tools;const found=a?.find(x=>x.id===id);return found?(kind==='stage'?(A()?.field?.('steps',found,'title')||found.title):title(kind==='metric'?'metrics':'tools',found)):id;}
  function numericSelect(key,label){const m=state.figure.mapping;return `<label class="lab-field"><span>${label==='x'?'X':label==='y'?'Y':T(label)}</span><select data-lab-map="${key}"><option value="">${T('choose')}</option>${m[key]&&!(state.dataset?.columns||[]).includes(m[key])?`<option value="${E(m[key])}" selected>${E(m[key])} · ${T('columnPending')}</option>`:''}${(state.dataset?.columns||[]).map(c=>`<option value="${E(c)}" ${m[key]===c?'selected':''}>${E(c)}</option>`).join('')}</select></label>`;}
  function mapping(){const c=state.figure;const keys=c.type==='scatter'?['x','y']:c.type==='effect'?['estimate','lower','upper']:['mean','error'];return `<div class="lab-two">${[...keys,'label','group'].map(k=>numericSelect(k,k)).join('')}</div>`;}
  function cfgInput(key,label,type='text',extra=''){return `<label class="lab-field"><span>${T(label)}</span><input type="${type}" data-lab-config="${key}" value="${E(state.figure[key])}" ${extra}></label>`;}
  function cfgSelect(key,label,opts){return `<label class="lab-field"><span>${T(label)}</span><select data-lab-config="${key}">${opts.map(([v,t])=>`<option value="${E(v)}" ${String(state.figure[key])===String(v)?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;}
  function figureControls(){return `<section class="lab-card lab-figure-controls"><div class="lab-card-head"><span class="lab-step">01</span><h2>${T('data')}</h2></div><p>${T('dataHint')}</p><div class="lab-actions"><label class="btn lab-file-button">${T('upload')}<input id="lab-data-file" type="file" accept=".csv,.tsv,.txt,text/csv,text/tab-separated-values"></label><button class="btn btn-quiet" data-lab="template">${T('template')}</button></div><details class="lab-details"><summary>${T('paste')}</summary><textarea id="lab-paste" rows="5" placeholder="${T('paste')}" aria-label="${T('paste')}"></textarea><button class="btn" data-lab="paste">${T('apply')}</button></details><div id="lab-data-summary">${dataSummary()}</div><p class="lab-small">${T('limitError')}</p><div class="lab-divider"></div><h3>${T('columns')}</h3>${cfgSelect('type','type',['scatter','effect','bar'].map(k=>[k,T(k)]))}<div id="lab-mapping">${mapping()}</div><div class="lab-divider"></div><h3>${T('appearance')}</h3>${cfgInput('name','figureName','text','maxlength="240"')}<div class="lab-two">${cfgSelect('font','font',['Arial','Helvetica','Verdana'].map(x=>[x,x]))}${cfgInput('fontSize','fontSize','number','min="5" max="12" step="0.5"')}${cfgSelect('width','width',[['single',T('single')],['double',T('double')],['custom',T('custom')]])}${cfgInput('widthMM','widthMM','number','min="60" max="300" step="1"')}${cfgSelect('palette','palette',[['okabe','Okabe–Ito'],['tol','Paul Tol · bright']])}${cfgInput('maxLabels','maxLabels','number','min="0" max="24" step="1"')}</div>${cfgInput('xTitle','xTitle','text','maxlength="240"')}${cfgInput('yTitle','yTitle','text','maxlength="240"')}${cfgSelect('reference','referenceLine',[['none',T('noneLine')],['0','0'],['1','1']])}<label class="lab-check"><input type="checkbox" data-lab-config="legend" ${state.figure.legend?'checked':''}>${T('legend')}</label><details class="lab-details"><summary>${T('description')}</summary>${['observation','replication','uncertainty','methods'].map(k=>`<label class="lab-field"><span>${T(k==='observation'?'unitOfObservation':k)}</span><textarea data-lab-config="${k}" rows="2" maxlength="3000">${E(state.figure[k])}</textarea></label>`).join('')}</details></section>`;}
  function dataSummary(){return state.dataset?`<div class="lab-import-summary"><strong>${E(state.dataset.name)}</strong><span>${state.dataset.rows.length} ${T('rows')} · ${state.dataset.columns.length}</span><button data-lab="clear" class="btn btn-quiet">${T('clear')}</button></div>`:'';}
  function specificationMapping(spec){const axis=k=>typeof spec.axes?.[k]==='object'?spec.axes[k].key:spec.axes?.[k]||'',columns=new Set((spec.columns||[]).map(c=>c.key));const mapping={...defaults().mapping,group:axis('color'),label:axis('label')||(spec.chartType==='effect'?axis('y'):columns.has('gene_id')?'gene_id':'')};if(spec.chartType==='scatter'){mapping.x=axis('x');mapping.y=axis('y');}else if(spec.chartType==='effect'){mapping.estimate=axis('x');mapping.lower='interval_low';mapping.upper='interval_high';}return mapping;}
  function supportsSpecification(spec){if(!spec||!['scatter','effect'].includes(spec.chartType))return false;const columns=new Set((spec.columns||[]).map(c=>c.key)),mapping=specificationMapping(spec),required=spec.chartType==='scatter'?['x','y']:['estimate','lower','upper'];return required.every(k=>columns.has(mapping[k]));}
  function prepareSpecification(spec){if(!supportsSpecification(spec))return false;pendingSpecification=JSON.parse(JSON.stringify(spec));tab='figures';refresh();return true;}
  function specificationBanner(){if(!pendingSpecification)return '';const s=pendingSpecification,m=specificationMapping(s);return `<section class="lab-specification-banner" aria-labelledby="lab-specification-title"><div><span class="lab-kicker">${T('pendingSpecification')}</span><h2 id="lab-specification-title">${E(A().tx(s.title))}</h2><p>${T('specificationChoice')}</p><dl>${Object.entries(m).filter(([,v])=>v).map(([k,v])=>`<div><dt>${E(k==='x'?'X':k==='y'?'Y':T(k))}</dt><dd><code>${E(v)}</code></dd></div>`).join('')}</dl></div><div class="lab-actions"><button class="btn btn-primary" data-lab="apply-specification">${T('applySpecification')}</button><button class="btn" data-lab="cancel-specification">${T('keepCurrent')}</button></div></section>`;}
  function applySpecification(){const s=pendingSpecification;if(!supportsSpecification(s))return;const m=specificationMapping(s),field=k=>A().tx(s.columns.find(c=>c.key===k)?.label||k);state.figure=cleanFigure({...state.figure,type:s.chartType,name:A().tx(s.title),mapping:m,xTitle:field(s.chartType==='effect'?m.estimate:m.x),yTitle:s.chartType==='scatter'?field(m.y):'',annotated:[],reference:'none',observation:'',replication:'',uncertainty:'',methods:'',specificationId:s.id,specificationSourceUrls:s.sourceUrls||[]});pendingSpecification=null;save();refresh();status(T('specificationApplied'));}
  function figurePanel(){return `<section class="lab-figure-output"><div class="lab-card lab-preview-card"><div class="lab-card-head"><span class="lab-step">02</span><h2>${T('preview')}</h2><span class="lab-draft">${T('draft')}</span></div><div id="lab-plot" class="lab-plot" role="img" aria-label="${T('preview')}"></div><div id="lab-plot-report" class="lab-plot-report" role="status"></div><div class="lab-actions lab-export-actions"><button class="btn btn-primary" data-lab="svg">${T('svg')}</button><button class="btn" data-lab="png">${T('png')}</button><button class="btn" data-lab="csv">${T('csv')}</button><button class="btn" data-lab="config">${T('config')}</button></div><p class="lab-small">${T('draftHint')}</p><p class="lab-small">${T('sizeGuide')}</p><a href="${GUIDE}" target="_blank" rel="noopener noreferrer">${T('guide')} ↗</a> · <a href="${SIZE_GUIDE}" target="_blank" rel="noopener noreferrer">90 / 180 mm ↗</a></div><section class="lab-card"><div class="lab-card-head"><span class="lab-step">03</span><h2>${T('markRows')}</h2></div><p class="lab-small">${T('markHint')}</p><div class="lab-row-toolbar"><input id="lab-row-search" type="search" value="${E(search)}" placeholder="${T('searchRows')}" aria-label="${T('searchRows')}"><button class="btn btn-quiet" data-lab="clear-labels">${T('clearLabels')}</button></div><div id="lab-row-list">${rowList()}</div></section></section>`;}
  function rowLabel(r,i){const idx=state.dataset?.columns.indexOf(state.figure.mapping.label);return idx>=0&&r[idx]?r[idx]:T('row')+' '+(i+1);}
  function rowList(){const d=state.dataset;if(!d)return `<p class="lab-small">${T('templateOnly')}</p>`;const found=d.rows.map((r,i)=>({r,i,label:rowLabel(r,i)})).filter(r=>r.label.toLowerCase().includes(search.toLowerCase()));const max=Math.max(1,Math.ceil(found.length/30));rowPage=Math.max(0,Math.min(rowPage,max-1));return `<div class="lab-rows">${found.slice(rowPage*30,(rowPage+1)*30).map(x=>`<label class="lab-row"><input type="checkbox" data-lab-row="${x.i}" ${state.figure.annotated.includes(x.i)?'checked':''}><span>${E(x.label)}</span><small>${x.i+1}</small></label>`).join('')}</div><div class="lab-row-pagination"><span>${found.length} ${T('rows')} · ${rowPage+1}/${max}</span><div><button class="btn" data-lab="rows-prev" ${rowPage===0?'disabled':''}>${T('previous')}</button><button class="btn" data-lab="rows-next" ${rowPage===max-1?'disabled':''}>${T('next')}</button></div></div>`;}
  function page(){return `<section id="lab-page" class="lab-page"><header class="lab-heading"><div><span class="lab-kicker">YEASTVAR1011 / DIY</span><h1>${T('title')}</h1><p>${T('subtitle')}</p></div><div class="lab-actions"><button class="btn" data-lab="export">${T('export')}</button><label class="btn lab-file-button" title="${T('importHint')}">${T('import')}<input id="lab-json-file" type="file" accept=".json,application/json"></label></div></header><p class="lab-scope">${T('scope')}</p>${specificationBanner()}<nav class="lab-tabs" aria-label="${T('title')}">${['formulas','figures'].map(t=>`<button data-lab="tab" data-id="${t}" class="${tab===t?'active':''}" aria-pressed="${tab===t}">${t==='formulas'?'∑':'↗'} ${T(t)}</button>`).join('')}</nav><div id="lab-status" class="lab-status" role="status" hidden></div><div class="lab-layout ${tab==='figures'?'lab-figure-layout':''}">${tab==='formulas'?formulaEditor()+formulaList():figureControls()+figurePanel()}</div><footer class="lab-footer">${T('local')}<br>${T('importHint')}</footer></section>`;}
  function refresh(){if(!root?.isConnected)return;const parent=root.parentNode;beforeRender();parent.innerHTML=page();afterRender();}
  function parseDelimited(raw,name='data.csv'){if(typeof raw!=='string'||new Blob([raw]).size>2097152)throw Error(T('limitError'));raw=raw.replace(/^\uFEFF/,'');const line=raw.split(/\r?\n/)[0]||'';let quote=false,commas=0,tabs=0;for(let i=0;i<line.length;i++){if(line[i]==='"')quote=!quote;else if(!quote){if(line[i]===',')commas++;if(line[i]==='\t')tabs++;}}const delimiter=tabs>commas?'\t':',';const table=[];let row=[],cell='',quoted=false,closed=false;function endCell(){row.push(cell);cell='';closed=false;}function endRow(){endCell();if(row.some(x=>x!==''))table.push(row);row=[];if(table.length>5001)throw Error(T('limitError'));}
    for(let i=0;i<raw.length;i++){const ch=raw[i];if(quoted){if(ch==='"'){if(raw[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=ch;continue;}if(ch==='"'){if(cell||closed)throw Error(T('parseError'));quoted=true;}else if(ch===delimiter)endCell();else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&raw[i+1]==='\n')i++;endRow();}else {if(closed)throw Error(T('parseError'));cell+=ch;}if(row.length>80||cell.length>50000)throw Error(T('limitError'));}if(quoted)throw Error(T('parseError'));if(cell||row.length||closed)endRow();if(!table.length)throw Error(T('parseError'));const columns=table.shift().map(s=>s.trim());return cleanDataset({name,columns,rows:table,importedAt:new Date().toISOString()});}
